<?php
require_once __DIR__.'/production.php';$recipes=productionRecipes();$edit=(int)($_GET['recipe']??0);$r=$recipes[$edit]??null;
if($_SERVER['REQUEST_METHOD']==='POST'&&($_POST['action']??'')==='recipe_save') {
 $edit=(int)($_POST['id']??0);$r=['name'=>pv('name'),'base_g'=>pv('base_g','1000'),'brine_group'=>pv('brine_group','none'),'ingredients'=>'[]'];$lines=[];foreach($_POST['material']??[] as $i=>$m)$lines[]=['material'=>is_string($m)?$m:'','basis'=>$_POST['basis'][$i]??'product','mode'=>$_POST['mode'][$i]??'percent','amount'=>$_POST['amount'][$i]??0];
} else $lines=$r?json_decode($r['ingredients'],true):[];
$materials=['배추','무우','절임소금','총각무','열무','갓','파'];foreach($recipes as $rec)foreach(json_decode($rec['ingredients'],true) as $line)$materials[]=$line['material'];$materials=array_unique($materials);
function recipeOptions(array $recipes,int $selected): void {echo '<option value="0">배합 기준 미등록</option>';foreach($recipes as $id=>$r)echo '<option value="'.(int)$id.'" '.($id===$selected?'selected':'').'>'.e($r['name']).'</option>';}
?>
